/** Disposable fictional project. No SDK query or provider transport. */
import { cpSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import type { ClassificationAnswers, ClassificationRequest } from "@schlessera/brain-ui-sdk/internal";
import type { BackendBridge, StartTurnRequest } from "@schlessera/brain-ui-sdk/server";
import { discoverSkills } from "../packages/core/src/lib/skills/discover.js";
import { claudeEmitter } from "../packages/core/src/lib/skills/emitters/claude.js";
import { assembleTurn, connectSurface, type SkillEntry, type Peer } from "./turn-surface-routing.js";
import cases from "./fixtures/turn-surface-cases.json";
import { DEFAULT_ALLOWED_TOOLS } from "../packages/ui-backend-claude/src/tool-policy.js";
import corpusConfig from "../packages/core/fixtures/corpus/brain.config.js";

export const FROZEN_CASES = cases;
export function createFixture(control?: { corpus?: boolean }) {
  const root = mkdtempSync(join(tmpdir(), "turn-surface-fixture-"));
  writeFileSync(join(root, "brain.config.json"), JSON.stringify({ profile: { name: "Odysseus" } }));
  mkdirSync(join(root, "me"));
  writeFileSync(join(root, "me/identity.md"), "---\ntitle: Odysseus\ntype: identity\n---\n\nOdysseus is preparing the next voyage.\n");
  if (control?.corpus) {
    cpSync(join(import.meta.dir, "../packages/core/fixtures/corpus"), root, { recursive: true });
    // The copied TS config imports a workspace package that is deliberately
    // absent from this outside-checkout fixture. The same config object is
    // supplied as literal data; document/skill content remains unchanged.
    rmSync(join(root, "brain.config.ts"));
    writeFileSync(join(root, "brain.config.json"), JSON.stringify(corpusConfig));
    writeFileSync(join(root, "CLAUDE.md"), "This is the fictional Odysseus notebook. Its current story date is 2026-07-12, independent of the runtime calendar. Odysseus is alone on Ogygia; his crew did not survive Thrinacia. Follow an existing project skill when the user requests its written procedure. Do not save drafts, change notebook files or settings, or invent completed construction. Use the notebook for facts about Odysseus; general explanations may be answered in prose.\n");
  }
  const restoreSkills = () => { for (const skill of cases.skills) {
    const dir = join(root, ".agents/skills", skill.name);
    mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, "SKILL.md"), `---\nname: ${skill.name}\ndescription: ${skill.description}\n---\n\nConsult the voyage notebook before recording a decision.\n`);
  } };
  restoreSkills();
  const discover = () => discoverSkills({ root, modules: [] }, { coreSkillsDir: join(root, "no-core-skills") });
  const discovered = discover();
  if (discovered.warnings.length || discovered.skills.length !== cases.skills.length) throw new Error("fixture skill discovery failed");
  const emitSkills = () => {
    const skills = discover().skills;
    const emitted = join(root, ".claude/skills");
    // Only this owned corpus fixture gets physical copies. The production
    // emitter deliberately preserves real directories, so rebuild the owned
    // output on every layout transition to remove rejected copies too.
    if (control?.corpus) rmSync(emitted, { recursive: true, force: true });
    claudeEmitter.emit(skills, root);
    if (control?.corpus) for (const skill of skills) {
      const target = join(emitted, skill.name);
      rmSync(target);
      cpSync(skill.dir, target, { recursive: true });
    }
  };
  emitSkills();
  return {
    root, skills: discovered.skills.map(({ name, description }) => ({ name, description })) satisfies SkillEntry[],
    restoreSkills() { restoreSkills(); emitSkills(); },
    skillFiles: () => Object.fromEntries(readdirSync(join(root, ".claude/skills")).sort().map(name => [name, readFileSync(join(root, ".claude/skills", name, "SKILL.md"), "utf8")])),
    pruneSkills(names: readonly string[]) {
      // Sources and emitted entries are removed only in this disposable root.
      // Rejected skills cannot be manually read from their former source.
      for (const skill of discovered.skills) if (!names.includes(skill.name)) rmSync(skill.dir, { recursive: true });
      emitSkills();
    },
    close: () => rmSync(root, { recursive: true, force: true }),
  };
}

export async function fixtureTurn(root: string, prompt: string, posture: "normal" | "no-grant" | "autonomous" = "normal", attachments?: StartTurnRequest["attachments"], control?: {
  productionDefaults?: boolean;
  bridge?: Partial<BackendBridge>;
}) {
  const never = async () => { throw new Error("unexpected host interaction in fixture"); };
  let askUserCalls = 0;
  const bridge: BackendBridge = { emit: () => {}, checkpointPermission: () => {}, requestPermission: never,
    askUser: async () => { askUserCalls++; return { answers: { Harbour: "Ithaca" } }; },
    askUserList: never, askUserRank: never, askUserForm: never,
    getLocation: never, requestMask: never, queryActivity: never, ...control?.bridge };
  const abortController = new AbortController();
  const req: StartTurnRequest = {
    prompt, attachments, bridge, turnBudgetMs: 180_000, noGrantSurface: posture !== "normal",
    enforceAllowedTools: posture !== "normal", signal: abortController.signal,
    ...(posture === "autonomous" ? { autonomous: { origin: "autonomous" as const, persistence: "none" as const, allowedTools: ["Read"], systemPromptAppend: "Use only the server-authorized tools." } } : {}),
  };
  const input: Parameters<typeof assembleTurn>[0] = { backend: { brainPath: root }, req,
    profile: { id: "fixture", label: "Fixture", requiredEnvKeys: [], billing: "subscription", buildEnv: () => ({}) },
    abortController, allowedTools: posture === "autonomous" ? ["Read"] : control?.productionDefaults ? DEFAULT_ALLOWED_TOOLS : ["Read", "Bash"],
    confirmPatterns: [/rm/], turnLock: { acquire: async () => {}, release: () => {} } as never, log: () => {},
  };
  const turn = assembleTurn(input);
  // Inventory owns a separate real production instance. It must not occupy
  // the returned turn's transport before the SDK is able to connect to it.
  const inventoryTurn = assembleTurn(input);
  const server = inventoryTurn.options.mcpServers?.["brain-ui"];
  if (!server || server.type !== "sdk") throw new Error("production assembly did not supply its bridge server");
  const peer = await connectSurface("brain-ui", server);
  if (!peer.tools.length) throw new Error("production bridge listed no tools");
  return { turn, peer, askUserCalls: () => askUserCalls, close: async () => {
    await peer.client.close(); await server.instance.close();
    const original = turn.options.mcpServers?.["brain-ui"];
    if (original?.type === "sdk") await original.instance.close();
  } };
}

/** Version files beside the entry resolved from the backend, not root hoisting. */
export function installedRuntime() {
  const dir = dirname(Bun.resolveSync("@anthropic-ai/claude-agent-sdk", join(import.meta.dir, "../packages/ui-backend-claude/src")));
  return { agentSdk: JSON.parse(readFileSync(join(dir, "package.json"), "utf8")).version as string,
    claudeCode: JSON.parse(readFileSync(join(dir, "manifest.json"), "utf8")).version as string };
}

export async function connectBrainSurface(root: string): Promise<Peer> {
  const fixtureHome = join(root, ".fixture-home");
  mkdirSync(fixtureHome, { recursive: true });
  const client = new Client({ name: "turn-surface-core", version: "0.1.0" });
  // Exact environment: no account discovery, ambient provider keys or model
  // commands. This is the real stdio MCP server, not a Claude process.
  const transport = new StdioClientTransport({ command: process.execPath,
    args: [join(import.meta.dir, "../packages/core/src/mcp-server.ts")], cwd: root,
    env: { BRAIN_ROOT: root, HOME: fixtureHome, PATH: dirname(process.execPath) }, stderr: "pipe" });
  transport.stderr?.on("data", () => {});
  try {
    await client.connect(transport);
    const { tools } = await client.listTools();
    if (!tools.length) throw new Error("actual core server listed no tools");
    return { client, tools: tools.map(tool => ({ ...tool, id: `mcp__brain__${tool.name}`, serverName: "brain" })) };
  } catch (error) { await client.close(); throw error; }
}

/** Scripted answers are test inputs, never a model-quality observation. */
export function scriptedAnswers(request: ClassificationRequest, tool: string | null, skill: string | null): ClassificationAnswers {
  const answers: ClassificationAnswers = {};
  for (const [kind, picked] of [["tool", tool], ["skill", skill]] as const) {
    const question = request.questions[kind];
    if (question.type !== "choice") throw new Error("expected choice question");
    const winner = picked ?? Object.keys(question.criteria)[0];
    answers[kind] = { type: "choice", choice: winner, confidence: 0.99, probabilities: { [winner]: 0.99 } };
    answers[`needs_${kind}`] = { type: "noul", noul: picked ? 0.99 : 0.01 };
    for (const name of Object.keys(question.criteria)) answers[`fits_${kind}:${name}`] = { type: "noul", noul: name === winner ? 0.99 : 0.01 };
  }
  return answers;
}

sources.scripts/turn-surface-isolation.ts:
/** Uniform fixture-only denial layer for the private #587 research arms. */
import type { HookCallback } from "@anthropic-ai/claude-agent-sdk";
import { measurementIsolationHook, measurementPath, type MeasurementToolAccess } from "./measurement-isolation";
import type { SurfaceDecision } from "./turn-surface-overlap";

const READ_ONLY_CORE = ["brain_search", "brain_context", "brain_read", "brain_list", "brain_graph"];
export function routingMeasurementHook(root: string, knownSkills: readonly string[], decision: Promise<SurfaceDecision>, audit: MeasurementToolAccess[]): HookCallback {
  const filesystem = measurementIsolationHook(root, "mcp__brain-ui__show_block", audit);
  return async (input, toolUseId, options) => {
    if (input.hook_event_name !== "PreToolUse") return {};
    const data = input.tool_input as Record<string, unknown>;
    let admitted = false;
    if (input.tool_name === "ToolSearch") admitted = true;
    else if (input.tool_name === "Skill") {
      const selected = await decision;
      admitted = typeof data.skill === "string" && knownSkills.includes(data.skill)
        && (!selected.routed || selected.arm !== "hard-prune" || selected.skills.includes(data.skill));
    } else if (READ_ONLY_CORE.some(name => input.tool_name === `mcp__brain__${name}`)) {
      admitted = input.tool_name !== "mcp__brain__brain_read"
        || (typeof data.path === "string" && measurementPath(root, data.path) !== null);
    } else if (input.tool_name.startsWith("mcp__brain-ui__") && input.tool_name !== "mcp__brain-ui__request_image_mask") admitted = true;
    if (admitted) {
      audit.push({ tool: input.tool_name, allowed: true, target: "fixture-host-or-read-only" });
      return {};
    }
    // Reuse the already native-proven realpath guard for filesystem reads;
    // shell, writes, delegation and unknown tools remain uniformly denied.
    return filesystem(input, toolUseId, options);
  };
}

sources.scripts/turn-surface-observation.ts:
/** Runtime observations, independent of the router's predicted choices. */
import { BRIDGE_TOOL_CONTRACTS } from "@schlessera/brain-ui-sdk/server";

export interface ObservedCall { id: string; name: string; input: Record<string, unknown>; accepted: boolean; skill: string | null }
export interface RoundTripUsage {
  id: string; model: string; inputTokens: number; outputTokens: number;
  cacheReadTokens: number; cacheWriteTokens: number;
  cacheCreation: Record<string, unknown> | null;
}
function tokens(value: unknown): number | null { return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : null; }
function object(value: unknown): Record<string, unknown> | null { return value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, unknown> : null; }

export class TurnObservation {
  readonly calls = new Map<string, ObservedCall>();
  readonly roundTrips = new Map<string, RoundTripUsage>();
  readonly answerParts = new Map<string, string>();
  readonly finalOutputTokens = new Map<string, number>();
  private streamMessageId: string | null = null;
  firstFrameMs: number | null = null;
  firstTextMs: number | null = null;
  completed = false;
  observationError: string | null = null;
  constructor(private readonly started: number, private readonly model: string) {}

  observe(value: unknown, now = performance.now()): void {
    const frame = object(value);
    if (!frame) return;
    if (frame.type === "result") {
      this.completed = frame.subtype === "success";
      return;
    }
    if (frame.type === "stream_event" && frame.parent_tool_use_id === null) {
      const event = object(frame.event);
      if (this.firstFrameMs === null) this.firstFrameMs = now - this.started;
      if (event?.type === "message_start") {
        const message = object(event.message);
        if (typeof message?.id !== "string" || message.model !== this.model) {
          this.observationError = "Missing stream message id or unexpected model";
          this.streamMessageId = null;
        } else this.streamMessageId = message.id;
      }
      if (event?.type === "message_delta") {
        const output = tokens(object(event.usage)?.output_tokens);
        if (!this.streamMessageId || output === null) this.observationError = "Missing final streamed output usage";
        else {
          // Provider deltas report cumulative output, not increments. The
          // assistant envelope can retain the provisional message-start count.
          this.finalOutputTokens.set(this.streamMessageId, output);
          const trip = this.roundTrips.get(this.streamMessageId);
          if (trip) trip.outputTokens = output;
        }
      }
      if (event?.type === "content_block_delta" && object(event.delta)?.type === "text_delta" && this.firstTextMs === null) {
        this.firstTextMs = now - this.started;
      }
    }
    if (frame.type === "assistant" && frame.parent_tool_use_id === null) {
      const message = object(frame.message);
      const usage = object(message?.usage);
      if (typeof message?.id !== "string" || message.model !== this.model || !usage) {
        this.observationError = "Missing assistant usage or unexpected model";
        return;
      }
      const input = tokens(usage.input_tokens), output = tokens(usage.output_tokens);
      const read = tokens(usage.cache_read_input_tokens ?? 0), write = tokens(usage.cache_creation_input_tokens ?? 0);
      if (input === null || output === null || read === null || write === null) {
        this.observationError = "Invalid assistant token usage";
        return;
      }
      this.roundTrips.set(message.id, { id: message.id, model: this.model, inputTokens: input,
        outputTokens: this.finalOutputTokens.get(message.id) ?? output,
        cacheReadTokens: read, cacheWriteTokens: write, cacheCreation: object(usage.cache_creation) });
      if (this.firstFrameMs === null) this.firstFrameMs = now - this.started;
      if (!Array.isArray(message.content)) return;
      this.answerParts.set(message.id, message.content.flatMap(raw => {
        const block = object(raw);
        return block?.type === "text" && typeof block.text === "string" ? [block.text] : [];
      }).join("\n"));
      for (const raw of message.content) {
        const content = object(raw);
        if (content?.type !== "tool_use" || typeof content.id !== "string" || typeof content.name !== "string") continue;
        const input = object(content.input);
        if (!input) continue;
        this.calls.set(content.id, { id: content.id, name: content.name, input, accepted: false,
          skill: content.name === "Skill" && typeof input.skill === "string" ? input.skill : null });
      }
    }
    // A parsed assistant request alone does not prove execution. Match the
    // actual tool result to its original id and count only successful results.
    if (frame.type === "user" && (frame.parent_tool_use_id === null || frame.parent_tool_use_id === undefined)) {
      const message = object(frame.message);
      if (!Array.isArray(message?.content)) return;
      for (const raw of message.content) {
        const result = object(raw);
        if (result?.type !== "tool_result" || typeof result.tool_use_id !== "string") continue;
        const call = this.calls.get(result.tool_use_id);
        if (!call || result.is_error === true) continue;
        const contract = BRIDGE_TOOL_CONTRACTS.find(tool => `mcp__brain-ui__${tool.name}` === call.name);
        call.accepted = !contract || contract.input.safeParse(call.input).success;
      }
    }
  }

  get finalUsageComplete() {
    return this.roundTrips.size > 0 && [...this.roundTrips.keys()].every(id => this.finalOutputTokens.has(id));
  }

  score(golden: { neededToolGroups: readonly (readonly string[])[]; neededSkill: string | null;
    contentChecks?: { scope: string; patterns: readonly string[] } }) {
    if (!this.completed) return { included: false, neededToolsHit: null, neededSkillHit: null, wrongSkill: null, needlessSkill: null, needlessTool: null };
    const accepted = [...this.calls.values()].filter(call => call.accepted);
    const skills = accepted.flatMap(call => call.skill ? [call.skill] : []);
    const observedTools = accepted.filter(call => call.name !== "Skill" && call.name !== "ToolSearch").map(call => call.name);
    return {
      included: true,
      neededToolsHit: golden.neededToolGroups.length ? golden.neededToolGroups.every(group => group.some(name => observedTools.includes(name))) : null,
      neededSkillHit: golden.neededSkill ? skills.includes(golden.neededSkill) : null,
      wrongSkill: golden.neededSkill ? skills.some(name => name !== golden.neededSkill) : null,
      needlessSkill: golden.neededSkill === null ? skills.length > 0 : null,
      needlessTool: !golden.neededSkill && !golden.neededToolGroups.length ? observedTools.length > 0 : null,
      contentPass: golden.contentChecks ? golden.contentChecks.patterns.every(pattern => new RegExp(pattern, "is").test(
        golden.contentChecks!.scope === "acceptedInputs" ? JSON.stringify(accepted.map(call => call.input))
          : [...this.answerParts.values()].join("\n"))) : null,
    };
  }
}

